def split_input(inputs:str = puzzle_input) ->  list[str]:
    splited_input = []
    tmp = ''
    count = 0
    for char in puzzle_input:
        if char == 'R' or char == 'L':
            count += 1

            if count == 1:
                tmp += char
            elif count == 2:
                splited_input.append(tmp)
                tmp = char
                count = 1
            else:
                print("[ERR] Splitting inputs.")
                exit()
        else:
            tmp += char
    
    return splited_input

split_puzzle_input = split_input(puzzle_input)

def get_password(split_input:list[str] = split_puzzle_input, start_index:int = 50) -> Optional[int]:
    dial = start_index
    count = 0
    for rotation in split_input:
        direction = rotation[0]
        amount = int(rotation[1:])
        #print(f"[DEBUG] rotation: {rotation}\n[DEBUG] dir/amount: {direction}/{amount}\n[DEBUG] dial before change: {dial}")

        if direction == 'R':
            dial += amount
        elif direction == 'L':
            dial -= amount
        else:
            print(f"[ERR] Parsing split input {rotation}.")
            exit()
        
        #print(f"[DEBUG] dial after change: {dial}")

        while dial > 99:
            dial -= 100
        while dial < 0:
            dial += 100
        
        #print(f"[DEBUG] dial after calibration: {dial}\n")

        if dial == 0:
            count += 1
    return count


